package cn.materialbox.app;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.lang.reflect.*;import java.util.concurrent.*;import org.json.*;
public class UpdateRecoveryChecks extends Instrumentation {
 int checks;AppUpdates test;
 public void onCreate(Bundle b){super.onCreate(b);start();}
 void stop()throws Exception{if(test!=null){Field f=AppUpdates.class.getDeclaredField("worker");f.setAccessible(true);((ScheduledExecutorService)f.get(test)).shutdownNow();test=null;}}
 void check(boolean v,String m){if(!v)throw new AssertionError(m);checks++;}
 JSONObject base()throws Exception{return new JSONObject().put("current","0.4.1").put("latest","0.4.2").put("state","ready").put("file",new File(getTargetContext().getExternalFilesDir(null),"updates/nonexistent-recovery-fixture.apk").getAbsolutePath()).put("total",276174805).put("downloaded",276174805).put("percent",100).put("message","安装包已核验，仅验证安装入口");}
 String restore(JSONObject value,long id)throws Exception{stop();getTargetContext().getSharedPreferences("update-recovery-check",0).edit().putString("state",value.toString()).putLong("downloadId",id).commit();test=new AppUpdates(getTargetContext(),"update-recovery-check","0.4.1",(f,j)->{throw new IOException("Unexpected validator for nonexistent fixture");});return new JSONObject(test.snapshot()).getString("state");}
 public void onStart(){Bundle out=new Bundle();boolean pass=false;try{
  SharedPreferences p=getTargetContext().getSharedPreferences("app-updates",0);JSONObject saved=new JSONObject(p.getString("state","{}"));out.putString("previousUpdateCache",new JSONObject().put("state",saved.optString("state")).put("latest",saved.optString("latest")).put("hasUrl",saved.has("url")).put("downloadId",p.getLong("downloadId",-1)).put("fileExists",new File(saved.optString("file")).isFile()).toString());
  check("idle".equals(restore(base(),-1)),"orphan test ready cache must reset to idle");
  check("idle".equals(restore(base().put("state","downloading"),-1)),"orphan downloading cache must reset");
  JSONObject legitimate=base().put("schema",2).put("source","github:shuizhaodemumu/materialbox").put("tag","v0.4.2").put("name","MaterialBox-0.4.2-arm64.apk").put("url","https://github.com/shuizhaodemumu/materialbox/releases/download/v0.4.2/MaterialBox-0.4.2-arm64.apk").put("digest","");
  check("idle".equals(restore(legitimate,-1)),"missing cached APK resets without erasing user data");
  check("idle".equals(restore(legitimate.put("state","available"),-1)),"available cache must request fresh release next time");
  check("idle".equals(restore(legitimate.put("state","ready").put("url","https://example.invalid/test.apk"),12)),"untrusted cached URL rejected");
  check("idle".equals(restore(new JSONObject().put("state","ready").put("latest","broken"),-1)),"malformed cache self-heals");
  stop();ByteArrayOutputStream metadata=new ByteArrayOutputStream();try(InputStream in=getContext().getAssets().open("update-release-archived.json")){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)metadata.write(b,0,n);}JSONObject active=AppUpdates.release(new JSONObject(metadata.toString("UTF-8")),"0.2.9");File dir=new File(getTargetContext().getExternalFilesDir(null),"updates");dir.mkdirs();File download=new File(dir,"recovery-active-download.apk");DownloadManager dm=(DownloadManager)getTargetContext().getSystemService(Context.DOWNLOAD_SERVICE);long id=dm.enqueue(new DownloadManager.Request(android.net.Uri.parse(active.getString("url"))).setDestinationUri(android.net.Uri.fromFile(download)).setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE));try{try(android.database.Cursor row=dm.query(new DownloadManager.Query().setFilterById(id))){if(row!=null&&row.moveToFirst()){String local=row.getString(row.getColumnIndexOrThrow(DownloadManager.COLUMN_LOCAL_URI));out.putString("resumeProbe",new JSONObject().put("status",row.getInt(row.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS))).put("originalUrlMatches",active.getString("url").equals(row.getString(row.getColumnIndexOrThrow(DownloadManager.COLUMN_URI)))).put("localUri",local==null?"null":local).put("expectedPath",download.getCanonicalPath()).toString());}}active.put("file",download.getAbsolutePath()).put("state","downloading");getTargetContext().getSharedPreferences("update-recovery-check",0).edit().putString("state",active.toString()).putLong("downloadId",id).commit();test=new AppUpdates(getTargetContext(),"update-recovery-check","0.2.9",(f,j)->{throw new IOException("No full download intended");});check("downloading".equals(new JSONObject(test.snapshot()).optString("state")),"valid real DownloadManager transfer resumes");test.cancel();check("cancelled".equals(new JSONObject(test.snapshot()).optString("state")),"resumed download cancels");}finally{dm.remove(id);download.delete();stop();}
  AppUpdates real=AppUpdates.get(getTargetContext());JSONObject initial=new JSONObject(real.snapshot());check(!initial.optString("latest").equals("0.4.2"),"production must not revive fixture 0.4.2");real.check();long end=SystemClock.elapsedRealtime()+45000;JSONObject live;do{Thread.sleep(250);live=new JSONObject(real.snapshot());}while("checking".equals(live.optString("state"))&&SystemClock.elapsedRealtime()<end);check("current".equals(live.optString("state"))&&"0.4.1".equals(live.optString("latest")),"live GitHub current must be 0.4.1: "+live.optString("message"));out.putString("realLatest",live.optString("latest"));pass=true;out.putString("result","UPDATE_RECOVERY_PASS: "+checks);
 }catch(Throwable e){out.putString("result","UPDATE_RECOVERY_FAIL after "+checks+": "+e);}finally{try{stop();}catch(Exception ignored){}getTargetContext().getSharedPreferences("update-recovery-check",0).edit().clear().commit();}finish(pass?-1:0,out);}
}
